cypress_script:
describe('Shopping Cart', () => {
  before(() => {
    cy.visit('https://www.saucedemo.com/')
    cy.get('[data-test="username"]').type('standard_user')
    cy.get('[data-test="password"]').type('secret_sauce')
    cy.get('[data-test="login-button"]').click()
  })
  it('should display the shopping cart page with items', () => {
    cy.visit('https://www.saucedemo.com/cart.html')
    cy.url().should('include', '/cart.html')
    cy.get('[data-test="title"]').should('be.visible').and('contain', 'Your Cart')
    cy.get('[data-test="continue-shopping"]').should('be.visible')
    cy.get('[data-test="checkout"]').should('be.visible')
    cy.get('[data-test="cart-quantity-label"]').should('be.visible')
    cy.get('[data-test="cart-desc-label"]').should('be.visible')
  })
  it('should allow the user to continue shopping', () => {
    cy.visit('https://www.saucedemo.com/cart.html')
    cy.get('[data-test="continue-shopping"]').click()
    cy.url().should('include', '/inventory.html')
  })
})

playwright_script:
import { test } from '@playwright/test';

 test.describe('Shopping Cart', () => {
   test.beforeEach(async ({ page }) => {
      await page.goto('https://www.saucedemo.com/')
      await page.fill('[data-test="username"]', 'standard_user')
      await page.fill('[data-test="password"]', 'secret_sauce')
      await page.click('[data-test="login-button"]')
   });
   test('should display the shopping cart page with items', async ({ page }) => {
      await page.goto('https://www.saucedemo.com/cart.html');
      await expect(page).toHaveURL(/.*cart.html/);
      await expect(page.locator('[data-test="title"]').textContent()).toContain('Your Cart');
      await expect(page.locator('[data-test="continue-shopping"]').isVisible()).toBeTruthy();
      await expect(page.locator('[data-test="checkout"]').isVisible()).toBeTruthy();
      await expect(page.locator('[data-test="cart-quantity-label"]').isVisible()).toBeTruthy();
      await expect(page.locator('[data-test="cart-desc-label"]').isVisible()).toBeTruthy();
   });
   test('should allow the user to continue shopping', async ({ page }) => {
      await page.goto('https://www.saucedemo.com/cart.html');
      await page.click('[data-test="continue-shopping"]');
      await expect(page).toHaveURL(/.*inventory.html/);
   });
});
